from flask import Blueprint, jsonify, request

from src.billing import refunds

from . import errors
from .invoices import _INVOICES

bp = Blueprint("refunds", __name__)

IDEMPOTENCY_TTL_SECONDS = 24 * 60 * 60

# idempotency key -> (stored_at, body, status)
_IDEMPOTENCY = {}


@bp.post("/invoices/<invoice_id>/refunds")
def create_refund(invoice_id):
    key = request.headers.get("X-Acme-Idempotency")
    if not key:
        return errors.problem(428, "Idempotency key required", "Send the X-Acme-Idempotency header.")
    stored = _IDEMPOTENCY.get(key)
    if stored and time.time() - stored[0] < IDEMPOTENCY_TTL_SECONDS:
        return jsonify(stored[1]), stored[2]

    actor_id = request.headers.get("X-Acme-Actor-Id")
    if not actor_id:
        return errors.problem(401, "Actor required", "Send the X-Acme-Actor-Id header.")

    invoice = _INVOICES.get(invoice_id)
    if invoice is None:
        return errors.problem(404, "Invoice not found")

    payload = request.get_json(silent=True) or {}
    amount = payload.get("amount")
    if not isinstance(amount, dict):
        return errors.problem(422, "Invalid amount", 'Expected {"minor": <int>, "ccy": <str>}.')
    minor = amount.get("minor")
    if type(minor) is not int:
        return errors.problem(422, "Invalid amount", "amount.minor must be an integer.")
    if amount.get("ccy") != invoice.currency:
        return errors.problem(422, "Currency mismatch", f"Invoice is in {invoice.currency}.")

    try:
        result = refunds.refund(invoice, minor, actor_id=actor_id)
    except ValueError as exc:
        return errors.problem(422, "Refund rejected", str(exc))

    body = {
        "invoice_id": result["invoice_id"],
        "amount": {"minor": result["refunded_cents"], "ccy": invoice.currency},
        "status": result["status"],
    }
    status = 201 if result["status"] == "issued" else 202
    _IDEMPOTENCY[key] = (time.time(), body, status)
    return jsonify(body), status
